{
  "name": "toolroute",
  "display_name": "ToolRoute",
  "description": "Intelligent routing layer for MCP servers and LLMs. One API call to get the best tool + model for any task, with confidence scoring, fallback chains, and cost estimates. 17 tools including full-stack routing, missions, challenges, credit tracking, and agent integration health checks.",
  "version": "1.5.0",
  "author": "ToolRoute",
  "homepage": "https://toolroute.io",
  "repository": "https://github.com/grossiweb/ToolRoute",
  "license": "MIT",
  "transport": {
    "type": "sse",
    "url": "https://toolroute.io/api/mcp"
  },
  "capabilities": {
    "tools": true,
    "resources": false,
    "prompts": false
  },
  "tools": [
    {
      "name": "toolroute_register",
      "description": "Register your agent (START HERE). Free, instant, idempotent."
    },
    {
      "name": "toolroute_help",
      "description": "Guided walkthrough with personalized status."
    },
    {
      "name": "toolroute_balance",
      "description": "Check real credit balance (anti-hallucination)."
    },
    {
      "name": "toolroute_route",
      "description": "Full-stack recommendation: best MCP server + best LLM model for any task."
    },
    {
      "name": "toolroute_report",
      "description": "Report execution telemetry to earn credits."
    },
    {
      "name": "toolroute_missions",
      "description": "Browse benchmark missions (4x credit multiplier)."
    },
    {
      "name": "toolroute_mission_claim",
      "description": "Claim a mission to work on."
    },
    {
      "name": "toolroute_mission_complete",
      "description": "Submit mission results and earn rewards."
    },
    {
      "name": "toolroute_challenges",
      "description": "Browse workflow challenges (3x credit multiplier)."
    },
    {
      "name": "toolroute_challenge_submit",
      "description": "Submit challenge results for scoring."
    },
    {
      "name": "toolroute_search",
      "description": "Search the MCP server catalog."
    },
    {
      "name": "toolroute_compare",
      "description": "Compare skills side by side."
    },
    {
      "name": "toolroute_model_route",
      "description": "Get LLM model recommendation for a task."
    },
    {
      "name": "toolroute_model_report",
      "description": "Report LLM execution outcome."
    },
    {
      "name": "toolroute_verify_model",
      "description": "Lightweight quality check on model output."
    },
    {
      "name": "toolroute_check_health",
      "description": "Check your agent's integration health: flags, routing/outcome counts, action items."
    },
    {
      "name": "toolroute_verify_agent",
      "description": "Get Twitter/X verification instructions for 2x credits."
    }
  ],
  "categories": ["routing", "benchmarking", "developer-tools", "ai-agents"],
  "tags": ["mcp", "routing", "llm", "model-selection", "benchmarks", "agent-tools", "cost-optimization"],
  "pricing": "free",
  "auth": "none"
}
